#!/usr/bin/env bash

set -e
set -o pipefail

types="feat|fix|build|chore|ci|docs|style|refactor|perf|test|revert"
pattern="^(${types})(\([[:alnum:]_./-]+\))?!?: [^[:space:]](.*[^[:space:]])?$"

# messages generated by git itself (merges, reverts, autosquash) are allowed
skip_pattern='^(Merge |Revert "|fixup! |squash! |amend! )'

msg_file=$1

if [ ! -f "${msg_file}" ]; then
    echo "no such file: ${msg_file}" >&2
    exit 1
fi

# git runs this hook before stripping comments, so look for the first
# non-comment, non-empty line and stop at the scissors line of `commit -v`
subject=$(awk '/^# -+ >8 -+$/ {exit} /^#/ {next} NF {print; exit}' "${msg_file}")

# empty messages are rejected by git itself
if [ -z "${subject}" ]; then
    exit 0
fi

if [[ "${subject}" =~ ${skip_pattern} ]]; then
    exit 0
fi

if ! [[ "${subject}" =~ ${pattern} ]]; then
    {
        echo "Commit message:"
        echo "---"
        echo "${subject}"
        echo "---"
        echo ""
        echo "Your commit message does not seem to follow the conventional commit message format."
        echo "Expected: <type>[(scope)][!]: <description>, with type one of: ${types//|/, }"
        echo "Check https://www.conventionalcommits.org"
    } >&2
    exit 1
fi
